// Generated by /ship coverage audit
// Value: protects=the translation eval's structure grade passes only output that keeps blocks, inline tags, URLs and <pre> text of the source;
//   fails_when=block order, an inline tag count, a dropped or rewritten href/src, or a changed <pre> byte stops lowering the grade;
//   why_new=structureGrade had no test, so an eval run could report markup_ok for output that broke links or code;
//   seam=none;
//   no_claim=green does not prove real model output keeps its markup or that these checks are the right bar.
import { describe, expect, test } from "bun:test";
import { processArticleHtml } from "../../../../../../apps/api/src/modules/articles/reader/content/sanitize";
import { structureGrade } from "../../../../../../scripts/evals/translation/structure";

// The eval prepares each case's source HTML with this sanitizer pass; only the model output is raw.
const sanitized = (html: string) => processArticleHtml(html, { sanitizerVersion: null }).html;

const SOURCE = sanitized(
  [
    "<h2>Title</h2>",
    '<p>Read <a href="https://example.com/a">the post</a> and <a href="https://example.com/b">the docs</a>, <strong>now</strong> or <em>later</em>.</p>',
    "<ul><li>One</li><li>Two</li></ul>",
    '<pre><code class="language-js">let a = 1;\n  if (a &lt; 2) {}\n</code></pre>',
    '<figure><img src="https://example.com/i.png" alt="Chart"><figcaption>Caption</figcaption></figure>',
  ].join(""),
);

/** The source with its text translated and the given markup edits applied. */
function translated(edit: (html: string) => string = (html) => html): string {
  return edit(
    sanitized(
      [
        "<h2>Titel</h2>",
        '<p>Lesen Sie <a href="https://example.com/a">den Beitrag</a> und <a href="https://example.com/b">die Doku</a>, <strong>jetzt</strong> oder <em>später</em>.</p>',
        "<ul><li>Eins</li><li>Zwei</li></ul>",
        '<pre><code class="language-js">let a = 1;\n  if (a &lt; 2) {}\n</code></pre>',
        '<figure><img src="https://example.com/i.png" alt="Diagramm"><figcaption>Beschriftung</figcaption></figure>',
      ].join(""),
    ),
  );
}

describe("structureGrade", () => {
  test("accepts identical markup and translated text with equivalently formatted markup", () => {
    const perfect = {
      markup_ok: 1,
      url_keep: 1,
      details: { blocksMatch: true, inlineKeep: 1, codeKept: true, sourcePre: 1 },
    };

    expect(structureGrade(SOURCE, SOURCE)).toEqual(perfect);
    expect(structureGrade(SOURCE, translated())).toEqual(perfect);

    // The model need not reproduce the sanitizer's exact serialization: quotes and tag case differ.
    const loose = [
      "<H2>Titel</H2>",
      "<P>Lesen Sie <A HREF='https://example.com/a'>den Beitrag</A> und <A HREF='https://example.com/b'>die Doku</A>, <STRONG>jetzt</STRONG> oder <EM>später</EM>.</P>",
      "<UL><LI>Eins</LI><LI>Zwei</LI></UL>",
      '<PRE><CODE class="language-js">let a = 1;\n  if (a &lt; 2) {}\n</CODE></PRE>',
      "<FIGURE><IMG SRC='https://example.com/i.png' ALT='Diagramm'><FIGCAPTION>Beschriftung</FIGCAPTION></FIGURE>",
    ].join("");
    expect(structureGrade(SOURCE, loose)).toEqual(perfect);
  });

  test("grades an article with no URLs and no code as fully kept", () => {
    const plain = sanitized("<h2>Title</h2><p>Just text.</p>");

    expect(structureGrade(plain, "<h2>Titel</h2><p>Nur Text.</p>")).toEqual({
      markup_ok: 1,
      url_keep: 1,
      details: { blocksMatch: true, inlineKeep: 1, codeKept: true, sourcePre: 0 },
    });
  });

  describe("URLs", () => {
    test("counts a link whose href was removed as not kept", () => {
      const grade = structureGrade(
        SOURCE,
        translated((html) => html.replace(' href="https://example.com/b"', "")),
      );

      expect(grade.url_keep).toBe(2 / 3);
      expect(grade.markup_ok).toBe(0);
    });

    test("counts a rewritten href or src as not kept", () => {
      const rewrittenLink = structureGrade(
        SOURCE,
        translated((html) => html.replace("https://example.com/a", "https://example.com/de/a")),
      );
      const rewrittenImage = structureGrade(
        SOURCE,
        translated((html) => html.replace("https://example.com/i.png", "https://cdn.test/i.png")),
      );

      expect(rewrittenLink.url_keep).toBe(2 / 3);
      expect(rewrittenImage.url_keep).toBe(2 / 3);
      expect(rewrittenLink.markup_ok).toBe(0);
      expect(rewrittenImage.markup_ok).toBe(0);
    });

    test("matches URLs as a multiset, so a repeated link must stay repeated", () => {
      const twice = sanitized(
        '<p><a href="https://example.com/x">one</a> and <a href="https://example.com/x">two</a></p>',
      );
      const once = '<p>eins und <a href="https://example.com/x">zwei</a></p>';

      const grade = structureGrade(twice, once);

      expect(grade.url_keep).toBe(0.5);
      expect(grade.markup_ok).toBe(0);
    });
  });

  describe("block order", () => {
    test.each([
      {
        change: "a heading moved after the figure",
        edit: (html: string) => html.replace(/^(<h2>.*?<\/h2>)(.*)(<\/figure>)$/s, "$2$3$1"),
      },
      {
        change: "a list item dropped",
        edit: (html: string) => html.replace("<li>Zwei</li>", ""),
      },
      {
        change: "a paragraph split in two",
        edit: (html: string) => html.replace(", <strong>", "</p><p><strong>"),
      },
      {
        change: "a paragraph added at the end",
        edit: (html: string) => `${html}<p>Anmerkung der Übersetzung</p>`,
      },
    ])("fails the block check for $change and leaves the other checks alone", ({ edit }) => {
      const grade = structureGrade(SOURCE, translated(edit));

      expect(grade.details.blocksMatch).toBe(false);
      expect(grade.markup_ok).toBe(0);
      expect(grade.url_keep).toBe(1);
      expect(grade.details.codeKept).toBe(true);
    });
  });

  describe("inline tags", () => {
    test("scores the shared share of inline tag counts and fails any difference", () => {
      // The source holds a:2 strong:1 em:1 code:1, so one missing or extra tag moves the share.
      const droppedStrong = structureGrade(
        SOURCE,
        translated((html) => html.replace(/<\/?strong>/g, "")),
      );
      expect(droppedStrong.details.inlineKeep).toBe(4 / 5);
      expect(droppedStrong.details.blocksMatch).toBe(true);
      expect(droppedStrong.url_keep).toBe(1);
      expect(droppedStrong.markup_ok).toBe(0);

      const addedEm = structureGrade(
        SOURCE,
        translated((html) => html.replace("<li>Eins</li>", "<li><em>Eins</em></li>")),
      );
      expect(addedEm.details.inlineKeep).toBe(5 / 6);
      expect(addedEm.markup_ok).toBe(0);

      const swapped = structureGrade(
        SOURCE,
        translated((html) => html.replace(/<(\/?)strong>/g, "<$1em>")),
      );
      expect(swapped.details.inlineKeep).toBe(4 / 6);
      expect(swapped.markup_ok).toBe(0);
    });
  });

  describe("<pre> text", () => {
    test.each([
      { change: "a changed word", from: "let a = 1;", to: "let b = 1;" },
      { change: "changed indentation", from: "\n  if (a", to: "\n if (a" },
      {
        change: "leading indentation added",
        from: '"language-js">let a',
        to: '"language-js">  let a',
      },
      { change: "a translated comment appended", from: "{}\n", to: "{} // Ende\n" },
    ])("fails when $change makes the text differ", ({ from, to }) => {
      const grade = structureGrade(
        SOURCE,
        translated((html) => html.replace(from, to)),
      );

      expect(grade.details.codeKept).toBe(false);
      expect(grade.details.blocksMatch).toBe(true);
      expect(grade.markup_ok).toBe(0);
    });

    test("fails when the code block is removed or an extra one is added", () => {
      const removed = structureGrade(
        SOURCE,
        translated((html) => html.replace(/<pre>.*<\/pre>/s, "")),
      );
      expect(removed.details).toMatchObject({ blocksMatch: false, codeKept: false, sourcePre: 1 });
      expect(removed.markup_ok).toBe(0);

      const added = structureGrade(
        SOURCE,
        translated((html) => `${html}<pre>extra</pre>`),
      );
      expect(added.details.codeKept).toBe(false);
      expect(added.markup_ok).toBe(0);
    });

    test("ignores trailing whitespace at the end of a code block", () => {
      const grade = structureGrade(
        SOURCE,
        translated((html) => html.replace("{}\n</code>", "{}</code>")),
      );

      expect(grade.details.codeKept).toBe(true);
      expect(grade.markup_ok).toBe(1);
    });
  });
});
